<script setup lang="ts">
import SelectField from '@/components/SelectField.vue'
import { uiText } from '@/i18n'

import { computed,ref,watch,onBeforeUnmount } from 'vue'
import { learningApi,type LearningSummary,type LearningMetrics } from '@/api/learning'
import { createRequestGuard } from '@/lib/requestGuard'
const props=defineProps<{userId?:number}>(),days=ref(30),stats=ref<LearningSummary>(),error=ref(''),busy=ref(false),guard=createRequestGuard()
const metric=ref<keyof LearningMetrics>('answers'),labels:Partial<Record<keyof LearningMetrics,string>>={answers:'词汇答题',words:'学习单词',cards:'复习卡',notes:'整理笔记',seconds:'活跃分钟'}
const value=(m:LearningMetrics)=>metric.value==='seconds'?Math.round(m.seconds/60):m[metric.value]
const maximum=computed(()=>Math.max(1,...(stats.value?.days.map(d=>value(d.metrics))||[])))
async function load(){const run=guard.start();busy.value=true;error.value='';stats.value=undefined;try{const data=await learningApi.statistics(days.value,props.userId,run.signal);if(run.current())stats.value=data}catch(e){if(run.current())error.value=(e as Error).message}finally{if(run.current())busy.value=false}}
watch(()=>[props.userId,days.value],load,{immediate:true});onBeforeUnmount(()=>guard.cancel())
const weekly=computed(()=>{const rows=stats.value?.days||[];const sum=(slice:typeof rows)=>slice.reduce((a,d)=>({answers:a.answers+d.metrics.answers,cards:a.cards+d.metrics.cards,seconds:a.seconds+d.metrics.seconds,active:a.active+(Object.values(d.metrics).some(n=>n>0)?1:0)}),{answers:0,cards:0,seconds:0,active:0});return {now:sum(rows.slice(-7)),before:sum(rows.slice(-14,-7)),comparable:rows.length>=14}})
const minutes=(s:number)=>`${Math.floor(s/3600)} 小时 ${Math.floor(s%3600/60)} 分钟`
function download(){if(!stats.value)return;const rows=[['日期','词汇答题次数','正确次数','当日去重单词数','复习卡次数','当日整理笔记数','活跃秒数'],...stats.value.days.map(d=>[d.date,d.metrics.answers,d.metrics.correct,d.metrics.words,d.metrics.cards,d.metrics.notes,d.metrics.seconds])];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='learning-statistics.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><section class="learning-statistics" :aria-label="uiText('学习统计')">
 <header><div><p class="page-kicker">LEARNING JOURNAL</p><h2>{{userId?uiText('用户学习统计'):uiText('我的学习统计')}}</h2></div><div class="research-actions"><SelectField><select v-model.number="days" class="field-input" :aria-label="uiText('学习统计范围')"><option :value="7">{{ uiText('最近 7 天') }}</option><option :value="30">{{ uiText('最近 30 天') }}</option><option :value="90">{{ uiText('最近 90 天') }}</option><option :value="365">{{ uiText('最近一年') }}</option></select></SelectField><button class="button button--ghost" :disabled="!stats" @click="download">{{ uiText('导出明细') }}</button></div></header>
 <p v-if="busy" role="status">{{ uiText('正在读取学习记录…') }}</p><p v-if="error" role="alert">{{ uiText(error) }} <button class="button" @click="load">{{ uiText('重试') }}</button></p>
 <template v-if="stats"><div class="learning-totals"><div><strong>{{stats.total.words}}</strong><span>{{ uiText('累计学习单词 · 去重') }}</span></div><div><strong>{{stats.total.answers}}</strong><span>{{ uiText('累计词汇答题') }}</span></div><div><strong>{{stats.total.cards}}</strong><span>{{ uiText('累计复习卡次数') }}</span></div><div><strong>{{stats.total.notes}}</strong><span>{{ uiText('累计整理笔记 · 去重') }}</span></div><div><strong>{{minutes(stats.total.seconds)}}</strong><span>{{ uiText('累计活跃学习时间') }}</span></div><div><strong>{{stats.activeDays}}</strong><span>{{ uiText('有学习记录的天数') }}</span></div></div>
 <aside class="weekly-recap"><h3>{{ uiText('最近七天回顾') }}</h3><p>{{ uiText('学习了') }} {{weekly.now.active}} {{ uiText('天，完成') }} {{weekly.now.answers}} {{ uiText('次词汇答题和') }} {{weekly.now.cards}} {{ uiText('次卡片复习，累计') }} {{minutes(weekly.now.seconds)}}。</p><p v-if="weekly.comparable">{{ uiText('比前七天') }}{{weekly.now.answers>=weekly.before.answers?uiText('多'):uiText('少')}} {{Math.abs(weekly.now.answers-weekly.before.answers)}} {{ uiText('次词汇练习。') }}{{weekly.now.active<3?uiText('可以先安排每天十分钟，优先复习到期内容。'):uiText('继续保持节奏，留意错词和薄弱知识点。')}}</p></aside><div class="research-actions learning-series-tabs"><button v-for="(label,key) in labels" :key="key" class="button button--ghost" :aria-pressed="metric===key" @click="metric=key">{{ uiText(label) }}</button></div>
 <div class="learning-bars" role="img" :aria-label="((labels[metric]) + uiText('每日趋势，下方数据表包含完整数值'))"><div v-for="d in stats.days" :key="d.date" class="learning-bar-track" :title="`${d.date} · ${labels[metric]} ${value(d.metrics)}`"><span :style="{height:Math.max(1,value(d.metrics)/maximum*100)+'%'}" /></div></div><div class="learning-axis"><span>{{stats.days[0]?.date}}</span><span>{{stats.days.at(-1)?.date}}</span></div>
 <details><summary>{{ uiText('查看每天的详细记录') }}</summary><div class="learning-table"><table><thead><tr><th>{{ uiText('日期') }}</th><th>{{ uiText('答题 / 正确') }}</th><th>{{ uiText('学习单词') }}</th><th>{{ uiText('复习卡') }}</th><th>{{ uiText('整理笔记') }}</th><th>{{ uiText('活跃时长') }}</th></tr></thead><tbody><tr v-for="d in [...stats.days].reverse()" :key="d.date"><td>{{d.date}}</td><td>{{d.metrics.answers}} / {{d.metrics.correct}}</td><td>{{d.metrics.words}}</td><td>{{d.metrics.cards}}</td><td>{{d.metrics.notes}}</td><td>{{minutes(d.metrics.seconds)}}</td></tr></tbody></table></div></details>
 <p class="research-hint">{{ uiText('按') }} {{stats.zoneId}} {{ uiText('的自然日记录。活跃时长从此功能启用后开始估算：仅统计可见学习页面，闲置一分钟后暂停；多标签页不重复累加。单词数表示学习过，不代表已掌握。笔记同日多次保存只计一篇。') }}</p></template>
</section></template>
<style scoped>
.learning-statistics{padding:30px 0;border-top:1px solid var(--line)}header{display:flex;justify-content:space-between;gap:20px;align-items:center}header h2{margin:6px 0 20px}select{width:auto}.learning-totals{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;margin:24px 0 32px}.learning-totals strong{display:block;font-size:25px;font-weight:500;font-variant-numeric:tabular-nums}.learning-totals span{display:block;color:var(--muted);font-size:12px;margin-top:7px}.learning-series-tabs{flex-wrap:wrap;margin-bottom:24px}.learning-series-tabs [aria-pressed=true]{border-color:var(--green);color:var(--green)}.learning-bars{display:flex;gap:3px;height:150px;align-items:end;border-bottom:1px solid var(--line);background:repeating-linear-gradient(to top,transparent 0,transparent 49px,var(--line-soft) 49px,var(--line-soft) 50px)}.learning-bar-track{height:100%;flex:1;display:flex;align-items:end;min-width:1px}.learning-bar-track span{display:block;width:100%;background:var(--green);opacity:.65;border-radius:3px 3px 0 0}.learning-bar-track:hover span{opacity:1}.learning-axis{display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin:8px 0 20px}summary{cursor:pointer}.learning-table{overflow:auto;margin-top:16px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line-soft);white-space:nowrap}th{font-weight:500;color:var(--muted)}.research-hint{line-height:1.8;margin-top:20px}@media(max-width:800px){.learning-totals{grid-template-columns:repeat(2,1fr)}header{flex-wrap:wrap}}

.select-field{width:auto}
</style>
